  // A medial fat pad supports the roof of the orbit above the inner corner.
  // Its broad union keeps a grazing key from catching a hard shelf.
  let cushion=exp(-sq((xy.x+0.86)/0.40)-sq((xy.y-0.56)/0.38));
  // Let the wet inner corner recede into the nasal tissue along an oblique crease.
  let nasalRecess=0.164*exp(-sq((xy.x+0.925)/0.152)-sq((xy.y+0.082-0.21*(xy.x+0.91))/0.107));
  let temporalRecess=0.046*exp(-sq((xy.x-0.914)/0.128)-sq((xy.y-0.09*(xy.x-0.91))/0.097));
  let groove=nasalRecess+temporalRecess;
  let cheek=0.22-groove+0.085*cushion+0.32*smoothstep(0.72,1.23,length(xy))+0.14*bridge+0.13*brow+relief;
  return mergeDistance(shell,(p.z-cheek)*0.87,0.006+0.070*cushion+0.23*smoothstep(0.02,0.22,e));
}
fn tissueNormal(p: vec3f,cl: f32,g: vec2f) -> vec3f {
  let k=vec2f(0.00092,-0.00092);
  return normalize(k.xyy*tissue(p+k.xyy,cl,g)+k.yyx*tissue(p+k.yyx,cl,g)
    +k.yxy*tissue(p+k.yxy,cl,g)+k.xxx*tissue(p+k.xxx,cl,g));
}
fn marchTissue(ro: vec3f,rd: vec3f,cl: f32,g: vec2f,limit: f32) -> f32 {
  var t=max(0.05,(ro.z-1.25)/max(-rd.z,0.01));
  for(var i=0;i<105;i++){
    let h=tissue(ro+rd*t,cl,g);
    if(h<0.00065){return t;}
    t+=max(h*0.65,0.00035);
    if(t>limit){break;}
  }
  var hi=limit;
  if(t>=hi || tissue(ro+rd*hi,cl,g)>0.0){return 100.0;}
  var lo=t;
  for(var k=0;k<13;k++){
    let mid=(lo+hi)*0.5;
    if(tissue(ro+rd*mid,cl,g)>0.0){lo=mid;}else{hi=mid;}
  }
  return hi;
}
var<private> bodyToWorld:mat3x3f;
var<private> displayBasis:mat3x3f;
var<private> eyeBasis:mat3x3f;
var<private> irisOffset:f32;
var<private> tintOffset:f32;
var<private> irisResponse:f32;
fn keyDir()->vec3f{return transpose(eyeBasis)*worldKey();}
fn worldKey() -> vec3f {
  let a=mix(params.keyAzimuth,0.6,params.environment);
  let e=mix(params.keyElevation,0.52,params.environment);
  return transpose(bodyToWorld)*vec3f(sin(a)*cos(e),sin(e),cos(a)*cos(e));
}
fn keyColor() -> vec3f {return mix(vec3f(1.0,0.79,0.64),vec3f(0.68,0.82,1.0),clamp(params.warmCool+params.environment*0.6,0.0,1.0));}
fn specular(n: vec3f,v: vec3f,l: vec3f,r: f32,f0: f32) -> f32 {
  let h=normalize(v+l);let nl=max(dot(n,l),0.0);let nv=max(dot(n,v),0.001);let nh=max(dot(n,h),0.0);let vh=max(dot(v,h),0.0);
  let a=max(r*r,0.008);let a2=a*a;let d=a2/(PI*pow(nh*nh*(a2-1.0)+1.0,2.0));
  let k=(r+1.0)*(r+1.0)/8.0;let visibility=1.0/((nv*(1.0-k)+k)*(nl*(1.0-k)+k)*4.0);
  return d*visibility*(f0+(1.0-f0)*pow(1.0-vh,5.0))*nl;
}

// Rigidly orient each photographic capture. All reflected rays see the same
// world (independent of globe pose). No bright decal is attached to the eye.
fn probeUv(r:vec3f,axis:vec3f,aim:vec2f,roll:f32)->vec2f {
  let lon=(aim.x-0.5)*2.0*PI;
  let lat=(0.5-aim.y)*PI;
  let f=vec3f(sin(lon)*cos(lat),sin(lat),cos(lon)*cos(lat));
  let h=vec3f(cos(lon),0,-sin(lon));
  let v=cross(f,h);
  let rt=normalize(cross(vec3f(0,1,0),axis));
  let up=cross(axis,rt);
  let horizontal=dot(r,rt);
  let vertical=dot(r,up);
  let direction=f*dot(r,axis)+h*(cos(roll)*horizontal-sin(roll)*vertical)
    +v*(sin(roll)*horizontal+cos(roll)*vertical);
  return vec2f(0.5+atan2(direction.x,direction.z)/(2.0*PI),0.5-asin(clamp(direction.y,-1.0,1.0))/PI);
}
fn radianceAt(uv:vec2f,origin:vec2f,size:vec2f)->vec3f {
  return exp2(15.0*plate(origin,size,vec2f(fract(uv.x),uv.y)))-1.0;
}
fn reflectedProbe(uv:vec2f,origin:vec2f,size:vec2f)->vec3f {
  let spread=0.0008+0.0024*params.highlightShape;
  return 0.5*radianceAt(uv,origin,size)+0.125*(radianceAt(uv+vec2f(spread,0),origin,size)
    +radianceAt(uv-vec2f(spread,0),origin,size)+radianceAt(uv+vec2f(0,spread),origin,size)
    +radianceAt(uv-vec2f(0,spread),origin,size));
}
fn roomRadiance(r:vec3f)->vec3f {
  let axis=bodyToWorld*worldKey();
  let worldRay=bodyToWorld*(eyeBasis*r);
  var warm=vec3f(0);
  var cool=vec3f(0);
  if(params.environment<1.0){
    let uv=probeUv(worldRay,axis,vec2f(0.583,0.345),-0.57);
    warm=reflectedProbe(uv,vec2f(1024,1024),vec2f(1024,512))*2.35;
  }
  if(params.environment>0.0){
    let uv=probeUv(worldRay,axis,vec2f(0.501,0.386),0.19);
    cool=reflectedProbe(uv,vec2f(1536,480),vec2f(512,256))*2.05;
  }
  let light=mix(warm,cool,params.environment);
  return light/(1.0+0.013*light)*params.highlightIntensity*params.lightIntensity;
}
fn lidLight(p: vec3f,cl: f32,g: vec2f) -> f32 {
  var vis=1.0;
  for(var i=0;i<8;i++) {
    let t=0.024+f32(i*i)*0.009;
    vis=min(vis,clamp(tissue(p+keyDir()*t,cl,g)/(0.27*t)+0.44,0.0,1.0));
  }
  return vis;
}

fn hueRotate(c: vec3f,angle: f32) -> vec3f {
  let k=normalize(vec3f(1));let a=angle*2.0*PI;
  return max(vec3f(0),c*cos(a)+cross(k,c)*sin(a)+k*dot(k,c)*(1.0-cos(a)));
}
// The two top quadrants hold albedos; the two lower ones hold calibrated
// iris discs. More inputs are unfilterable data textures, so interpolate
// within each quadrant without borrowing a texel from the adjacent plate.
fn atlasSample(base:vec2i,size:vec2i,uv:vec2f)->vec3f {
 let p=clamp(uv,vec2f(0),vec2f(1))*vec2f(size-vec2i(1));
 let i=vec2i(floor(p));let j=min(i+vec2i(1),size-vec2i(1));
 let f=fract(p);
 return mix(mix(textureLoad(inputTexture2,base+i,0).rgb,textureLoad(inputTexture2,base+vec2i(j.x,i.y),0).rgb,f.x),
            mix(textureLoad(inputTexture2,base+vec2i(i.x,j.y),0).rgb,textureLoad(inputTexture2,base+j,0).rgb,f.x),f.y);
}
fn characterPlate(tile:vec2i,uv:vec2f)->vec3f {
 return atlasSample(tile*887,vec2i(887),uv);
}
fn skinSample(q:vec2f)->vec3f {
 // Crossfade translated samples at tile boundaries to avoid mirrored
 // furrows and chevrons. Inside each cell the photographed anatomy is intact.
 let f=fract(q);let blend=smoothstep(vec2f(0.76),vec2f(1.0),f);
 let a=0.16+0.68*f;let b=0.16+0.68*(f-1.0);
 let tile=select(vec2i(select(0,1,params.skinBed>1.5),0),vec2i(0,2),params.skinBed>2.5);
 var color=characterPlate(tile,a);
 if(blend.x>0.0){color=mix(color,characterPlate(tile,vec2f(b.x,a.y)),blend.x);}
 if(blend.y>0.0){
   var other=characterPlate(tile,vec2f(a.x,b.y));
   if(blend.x>0.0){other=mix(other,characterPlate(tile,b),blend.x);}
   color=mix(color,other,blend.y);
 }
 return color;
}
fn nativeSkinTint(native:vec3f)->vec3f {
 if(params.skinLayer<=0.0 || abs(params.skinHue)<0.00001){return native;}
 return mix(native,hueRotate(native,params.skinHue),params.skinLayer);
}
fn tissuePalette(native:vec3f,sample:vec3f,rim:f32)->vec3f {
 let value=dot(native,vec3f(0.29,0.57,0.14));
 let scaled=params.skinBed>1.5 && params.skinBed<2.5;
 let tint=select(vec3f(1.04,1.11,1.16),vec3f(1.24,0.91,1.34),scaled);
 let frost=mix(sample,vec3f(dot(sample,vec3f(0.25,0.59,0.16))),0.28);
 // Transfer the relative tonal relief of the registered lids into the frost.
 // Its furrows then follow the tarsal fold during a blink.
 let anatomy=clamp(0.63+1.35*sqrt(max(value,0.0)),0.64,1.30);
 let cold=frost*tint*anatomy;
 let other=sample*select(vec3f(1.12,0.96,1.0),tint,scaled)*clamp(0.75+0.80*sqrt(max(value,0.0)),0.76,1.21);
 let albedo=hueRotate(select(cold,other,params.skinBed>1.5),params.skinHue);
 let mucosa=hueRotate(select(vec3f(0.19,0.235,0.28),vec3f(0.17,0.072,0.135),scaled),params.skinHue);
 let wet=select(mucosa,vec3f(0.31,0.114,0.125),params.skinBed>2.5)*(0.35+1.7*sqrt(max(value,0.0)));
 return mix(native,mix(albedo,wet,0.83*rim),params.skinLayer);
}
fn bedIris(angle:f32,v:f32)->vec3f {
 // The generated plates have round holes of radius 65–69 texels. Start at
 // 76 texels and remap the full annulus between the actual pupil and limbus.
 if(params.irisBed<0.5){
   let pp=vec2f(625,620)+mix(102.0,578.0,clamp(v,0.0,1.0))*vec2f(cos(angle),-sin(angle));
   return atlasSample(vec2i(1774,0),vec2i(1254),pp/1253.0);
 }
 if(params.irisBed>2.5){
   let uv=(vec2f(442,442)+mix(64.0,418.0,clamp(v,0.0,1.0))*vec2f(cos(angle),-sin(angle)))/886.0;
   return characterPlate(vec2i(1,2),uv);
 }
 let col=select(0,1,params.irisBed>1.5);
 let centre=select(vec2f(439.5,442.0),vec2f(441.0,442.5),col==1)/886.0;
 let radius=mix(76.0,424.0,clamp(v,0.0,1.0))/886.0;
 return characterPlate(vec2i(col,1),centre+radius*vec2f(cos(angle),-sin(angle)));
}
fn scleralSample(st:vec2f)->vec3f {
  return plate(vec2f(2048,0),vec2f(2048,1024),vec2f(fract(st.x),clamp(st.y,0.001,0.999)));
}
fn vesselSignal(st:vec2f,sampleRgb:vec3f)->f32 {
  // Compare absorption to the neighboring connective tissue. Broad warm
  // pigmentation is a different material signal from a capillary.
  let surround=0.25*(scleralSample(st+vec2f(0.009,0.010))+scleralSample(st-vec2f(0.009,0.010))
    +scleralSample(st+vec2f(-0.006,0.017))+scleralSample(st-vec2f(-0.006,0.017)));
  let redGreen=log(max(sampleRgb.r,0.02)/max(sampleRgb.g,0.02))-log(max(surround.r,0.02)/max(surround.g,0.02));
  let luminance=vec3f(0.25,0.62,0.13);
  let extinction=log(max(dot(surround,luminance),0.025)/max(dot(sampleRgb,luminance),0.025));
  return clamp(1.10*redGreen+0.50*extinction,0.0,0.74);
}
fn pupilRadius(p:vec2f,meanRadius:f32)->f32 {
 let strain=clamp((params.pupilOval+params.pupilAspect)*0.92,-log(0.91/meanRadius),log(0.91/meanRadius));
 let stretch=exp(strain);
 let angle=normalize(p+vec2f(0.0000001,0));
 return meanRadius/max(0.1,length(angle*vec2f(stretch,1.0/stretch)));
}
fn irisColor(p: vec2f,pupil: f32) -> vec3f {
  let r=length(p)/(0.389*opticScale);let ang=atan2(p.y,p.x)+irisOffset;
  let inner=pupilRadius(p,pupil);
  let v=clamp((r-inner)/(1.0-inner),0.0,1.0);
  let rgb=bedIris(ang,v);
  let lum=dot(rgb,vec3f(0.2126,0.7152,0.0722));
  var c=hueRotate(mix(vec3f(lum),rgb,params.irisSaturation),params.irisHue+tintOffset);
  c=pow(max(c,vec3f(0.001)),vec3f(params.irisContrast));
  let fiber=0.5+0.5*sin(ang*181.0+noise(vec2f(ang*35.0,r*5.0))*5.0+r*31.0);
  c*=1.0+params.radialDetail*(fiber-0.5)*(0.30+0.15*params.irisPattern);

  let collarette=exp(-sq((v-0.20)/0.065));
  c*=0.84+collarette*0.25;
  return c;
}
fn shadeGlobe(ro: vec3f,rd: vec3f,tEye: f32,g: vec2f,cl: f32,time: f32) -> vec3f {
  let o=rotateToEye(ro,g);let d=rotateToEye(rd,g);
  let tc=sphere(o,d,vec3f(0,0,capCenter),capRadius);
  let cp=o+d*min(tEye,tc);
  let eyeP=ro+rd*tEye;let n=normalize(eyeP);
  let local=o+d*tEye;
  let opening=orbitalXY(eyeP);
  let bounds=lidEdges(opening.x,cl,g);
  let above=bounds.x-opening.y; let below=opening.y-bounds.y;
  let side=0.91-abs(opening.x);
  let clearance=min(side,min(above,below))+0.018;
  let contact=smoothstep(0.0,0.205,clearance);
  // The upper margin projects a longer penumbra under a high source. In the
  // contact band the transmitted light takes on the color of the lid.
  let upperShadow=smoothstep(-0.021,0.104+0.096*keyDir().y,above);
  let contactUpper=(1.0-0.61*exp(-max(above+0.014,0.0)/0.022));
  let contactLower=(1.0-0.71*exp(-max(below+0.018,0.0)/0.035));
  let crevice=mix(1.0,contactUpper*contactLower,params.contactOcclusion);
  let cornerShadow=smoothstep(-0.01,0.155,side);
  let skyVisibility=mix(0.19,1.0,contact)*mix(0.61,1.0,upperShadow);

  // The material is a sheet in longitude and latitude of the ROTATING eye.
  // Longitude advances at a constant rate along the horizontal great circle.
  // A low vascular contrast at the limbus is a pigment change, never a UV warp.
  let meridian=acos(clamp(local.z,-1.0,1.0));
  let lon=atan2(local.x,local.z);
  let lat=asin(clamp(local.y,-1.0,1.0));
  let latChart=0.5-2.0*lat/PI;
  let st=vec2f(fract(0.58+lon/PI),1.0-abs(2.0*fract(latChart*0.5)-1.0));
  let surface=plate(vec2f(2048,0),vec2f(2048,1024),st);
  let ivory=vec3f(0.77,0.75,0.714);
  let opticalDensity=-log(max(surface,vec3f(0.012))/ivory);
  let bodyDensity=dot(opticalDensity,vec3f(0.45,0.45,0.10));
  let periphery=smoothstep(0.40,0.95,meridian);
  let vesselPigment=opticalDensity-vec3f(bodyDensity);
  let primary=vesselSignal(st,surface);
  // Sample a second, oblique superficial plexus on the globe. Its limbward
  // branches persist in a temporal wedge even when the deep bed there is pale.
  let plexusUv=vec2f(0.18+lon*0.37+lat*0.10,0.49-lat*0.43+0.055*sin(2.2*lon));
  let superficial=vesselSignal(plexusUv,scleralSample(plexusUv));
  let coldTint=max(0.0,-params.yellowing);
  let amberTint=smoothstep(0.45,1.0,params.yellowing);
  let veinInk=mix(vec3f(0.20,0.95,0.81),vec3f(1.13,0.78,0.40),coldTint);
  let vesselLoad=params.veinDensity*params.scleraRedness*(primary*(0.68+0.29*periphery)
    +superficial*(0.27+0.81*periphery))*veinInk;
  let pigmentInk=mix(vesselPigment,vec3f(vesselPigment.b,vesselPigment.g,vesselPigment.r),coldTint);
  let absorption=params.veinDensity*(bodyDensity*params.scleraVariation
    +pigmentInk*(0.20+0.29*params.scleraRedness));
  // Low-frequency pigment and the vascular plexus share globe coordinates.
  let marbling=noise(vec2f(lon,lat)*7.1+vec2f(2.3,4.7))*0.54+noise(vec2f(lon,lat)*18.7)*0.23+0.23*periphery;
  let pigmentDensity=coldTint*vec3f(0.62,0.27,0.07)+amberTint*vec3f(0.11,0.52,1.19);
  let sclera=exp(-pigmentDensity*(0.22+marbling)-params.scleraShade*vec3f(3.1,3.3,3.45))*ivory*exp(-absorption)*vec3f(1,1.0-0.036*params.yellowing,1.0-0.095*params.yellowing);
  // Visibility begins on the transparent cap, where the incident light enters.
  let directVisibility=lidLight(rotateFromEye(cp,g),cl,g)*mix(0.08,1.0,upperShadow)*mix(0.36,1.0,cornerShadow);
  let wrap=clamp((dot(n,keyDir())+0.14)/1.14,0.0,1.0);
  let indirect=vec3f(0.17,0.18,0.20)*skyVisibility;
  let bounce=vec3f(0.070,0.021,0.015)*(1.0-contact)*params.lightIntensity;
  let diffuseKey=keyColor()*wrap*params.lightIntensity*1.16*directVisibility;
  var color=sclera*((indirect+bounce)*exp(-vesselLoad*0.49)+diffuseKey*exp(-vesselLoad*1.16));
  // The limbus transmits less near the edge of the corneal window.
  // The visible pigment boundary is calculated separately at the iris hit.
  let windowRadius=length(cp.xy)/opticScale;
  let window=select(0.0,1.0-smoothstep(0.397,0.475,windowRadius),cp.z>0.65);
  let localN=normalize(local);
  let blendNormal=1.0-smoothstep(0.346,0.448,asin(clamp(sin(min(meridian,1.57))/opticScale,0.0,1.0)));
  let cn=normalize(mix(localN,normalize(cp-vec3f(0,0,capCenter)),blendNormal));
  if(window>0.0){

    // Effective air-to-aqueous refraction. The iris has a shallow dish and
    // sits well behind the cap. Solve the intersection on the transmitted ray.
    let refracted=refract(d,cn,1.0/mix(1.0,1.336,clamp(params.refraction,0.0,1.0)));
    let irisZ=capCenter+capRadius-0.223*opticScale;
    let curvature=0.085/opticScale;
    var depth=(irisZ-cp.z)/min(refracted.z,-0.001);
    for(var i=0;i<3;i++){
      let q=cp+refracted*depth;
      let residual=q.z-irisZ-curvature*dot(q.xy,q.xy);
      depth-=residual/min(-0.05,refracted.z-2.0*curvature*dot(q.xy,refracted.xy));
    }
    let ip=cp+refracted*depth;
    let r=length(ip.xy)/(0.389*opticScale);
    // Pupil recruitment trails the lid reaction and releases more slowly.
    let pupil=clamp(params.pupil+params.autonomy*params.pupilResponse*irisResponse,0.15,0.75);
    let keyEye=rotateToEye(keyDir(),g);
    let stroma=irisColor(ip.xy,pupil);
    let luma=vec3f(0.28,0.57,0.15);
    let frontValue=dot(stroma,luma);
    let neighbor=dot(irisColor(ip.xy+0.004*opticScale*normalize(keyEye.xy+vec2f(0.0001)),pupil),luma);
    let relief=clamp((frontValue-neighbor)/max(0.065,frontValue+neighbor),-0.72,0.72);
    let rearP=ip.xy+refracted.xy*(0.039*opticScale/max(-refracted.z,0.18));
    let rearAngle=atan2(rearP.y,rearP.x)+irisOffset;
    let rearInner=pupilRadius(rearP,pupil);
    let rearRadius=clamp((length(rearP)/(0.389*opticScale)-rearInner)/(1.0-rearInner),0.0,1.0);
    // Chromatic depth under a crypt has no second focused fibre outline.
    let deepSample=bedIris(rearAngle,rearRadius);
    let deepValue=dot(deepSample,luma);
    let pigment=hueRotate(mix(vec3f(deepValue),deepSample,params.irisSaturation),params.irisHue+tintOffset);
    let radial=normalize(vec3f(-2.0*curvature*ip.xy,1));
    let irisLight=(0.37+0.92*max(dot(radial,keyEye),0.0))*params.lightIntensity;
    let sideLight=dot(normalize(ip.xy+0.0001),normalize(keyEye.xy+0.0001));
    // Resolve crypt openings from LOCAL fibre relief. Absolute pigment color
    // would turn the whole darker pupillary zone into a second translucent disc.
    let opposite=dot(irisColor(ip.xy-0.007*opticScale*normalize(keyEye.xy+vec2f(0.0001)),pupil),luma);
    let localLight=0.5*(opposite+neighbor);
    let hollow=(localLight-frontValue)/max(0.015,localLight);
    let crypt=smoothstep(0.09,0.52,hollow)*(1.0-smoothstep(0.86,1.0,r));
    let deepChroma=pigment/max(0.030,dot(pigment,luma));
    let cryptColor=deepChroma*(0.78*frontValue+0.22*deepValue)*(0.30+0.12*sideLight)*irisLight;
    let anterior=stroma*(1.0+relief*(0.55+params.radialDetail))*irisLight*(0.82-0.23*sideLight);
    var under=mix(anterior,cryptColor,(0.49+0.17*params.irisPattern)*crypt);
    let frontAngle=atan2(ip.y,ip.x)+irisOffset;
    let frill=0.0035*sin(frontAngle*73.0)+0.003*sin(frontAngle*41.0);
    let rim=pupilRadius(ip.xy,pupil)+frill;
    let inPupil=1.0-smoothstep(rim-0.003,rim+0.004,r);
    under=mix(under,vec3f(0.0016,0.00085,0.00065),inPupil);
    under*=mix(0.50,1.0,skyVisibility)*mix(vec3f(0.33,0.24,0.21),vec3f(1),directVisibility);

    // Fibres terminate at slightly different radii. Only this tissue boundary
    // changes the pigment; the clear specular surface continues across it.
    let edgeNoise=noise(normalize(ip.xy+vec2f(0.00001))*41.0);
    let edgeR=r+(edgeNoise-0.5)*0.012;
    let oblique=1.0-clamp(dot(radial,-refracted),0.0,1.0);
    let melanin=params.limbalRing*(1.0-0.85*oblique)*0.19*smoothstep(0.875,0.99,edgeR);
    let lightInside=params.irisLight*stroma*(1.0-inPupil)*(0.40+0.60*contact)*(1.0-0.79*smoothstep(0.69,1.0,r));
    let transmitted=(under+lightInside)*(1.0-melanin*vec3f(1.0,0.93,0.80));
    let pigmentWeight=1.0-smoothstep(0.947,1.047+0.061*oblique,edgeR);
    color=mix(color,transmitted,window*pigmentWeight);
  }
  // The tear film covers the entire exposed globe. Its normal and Fresnel
  // response cross the limbus continuously irrespective of the iris hit.
  let fresnel=0.022+0.978*pow(1.0-clamp(dot(cn,-d),0.0,1.0),5.0);
  let reflected=rotateFromEye(reflect(d,cn),g);
  // Trace the reflected direction through the outer lid shell. Testing the
  // exit against the moving aperture occludes the environment at either lid
  // and both corners, including when the light is across from the camera.
  let outerPoint=rotateFromEye(cp,g);
  let b=dot(outerPoint,reflected);
  let exitDistance=max(0.0,-b+sqrt(max(0.0,b*b+1.087*1.087-dot(cp,cp))));
  let exitPoint=outerPoint+exitDistance*reflected;
  let exitEdge=aperture(orbitalXY(exitPoint),cl,g);
  let penumbra=0.021+0.19*exitDistance;
  let reflectionVis=1.0-smoothstep(-penumbra,penumbra,exitEdge);
  let lidBlock=mix(1.0,mix(0.055,1.0,reflectionVis)*(0.66+0.34*contact),params.contactOcclusion);
  color*=crevice;
  let pupilWet=clamp(params.wetness,0.0,1.0)*fresnel;
  color=color*(1.0-pupilWet)+roomRadiance(reflected)*pupilWet*lidBlock;
  // A concave circular meniscus rises into the free margin. Its tangent turns
  // toward the studio lamp only along part of the rim; the rest transmits the eye.
  let slope=(lidEdges(opening.x+0.009,cl,g).y-lidEdges(opening.x-0.009,cl,g).y)/0.018;
  let dist=(below+0.020)*inverseSqrt(1.0+slope*slope);
  let pooling=noise(vec2f(opening.x*10.0,3.1));
  let width=0.025+0.013*pooling;
  let across=clamp(dist/width,0.0,1.0);
  let coverage=(1.0-smoothstep(0.30,1.0,across))*smoothstep(-0.03,-0.004,dist)
    *smoothstep(-0.012,0.067,side)*params.wetness*(1.0-cl);
  let inner=vec3f(-slope,1,0);
  let acrossN=normalize(inner-n*dot(inner,n));
  let filmSlope=(0.63+0.28*pooling+0.14*noise(vec2f(opening.x*51.0,3.4)))*(1.0-across)/sqrt(max(0.065,1.0-sq(1.0-across)));
  let tearN=normalize(n+0.84*filmSlope*acrossN);
  let tearFresnel=0.025+0.975*pow(1.0-clamp(dot(tearN,-rd),0.0,1.0),5.0);
  let filmLight=roomRadiance(reflect(rd,tearN))*tearFresnel*(0.50+0.50*lidBlock);
  let reflectedFraction=(0.23+0.31*pooling)*smoothstep(0.01,0.16,side);
  let fluid=color*(1.0-tearFresnel*0.54)*vec3f(0.96,0.93,0.91)
    +reflectedFraction*filmLight/(1.0+2.2*filmLight);
  color=mix(color,fluid,coverage);
  let lakeDepth=(1.0-smoothstep(-0.93,-0.70,opening.x))*smoothstep(-0.99,-0.86,opening.x);
  let lake=lakeDepth*(1.0-smoothstep(0.013,0.096,abs(below-0.012)));
  color=mix(color,color*vec3f(0.72,0.35,0.30)+vec3f(0.045,0.014,0.012),lake*0.8);
  return color;
}
fn outerPlateUV(p:vec2f)->vec2f {
 return vec2f(0.462+0.252*p.x,0.458-0.504*p.y);
}
fn lidMap(world: vec3f,cl: f32,g: vec2f) -> vec3f {
  let p=vec3f(orbitalXY(world),world.z);
  let rest=restLids(p.x);
  let lids=lidEdges(p.x,cl,g);
  let upper=p.y>(lids.y+lids.x)*0.5;
  let original=select(rest.y,rest.x,upper);
  let moving=select(lids.y,lids.x,upper);
  let signY=select(-1.0,1.0,upper);
  let offset=abs(p.y-moving);
  let attach=1.0-smoothstep(0.015,0.62,offset);
  // Carry skin with each lid and pin the orbital folds. The turned-in rim samples
  // slightly outside the dark aperture across its thickness.
  // Distance from the moving margin is always mapped outward into its own
  // lid, including at full closure. Never interpolate through the empty scan.
  let materialDistance=signY*(p.y-moving);
  let orbitalAnchor=select(-1.12,1.25,upper);
  let stretch=(orbitalAnchor-original)/(orbitalAnchor-moving);
  // The inner roll may land inside the projected opening. Keep its UV
  // on the photographed lip, including at the acute nasal and temporal tips.
  let outwardDistance=0.5*(materialDistance+sqrt(materialDistance*materialDistance+0.00014));
  let skinDistance=outwardDistance*stretch;
  let y=original+signY*(skinDistance
         +(0.022+0.38*max(0.0,1.10-length(p)))*attach);
  let attachment=1.0-smoothstep(0.75,0.923,abs(p.x));
  let tipChart=mix(p.y,y,1.0-smoothstep(0.88,0.98,abs(p.x)));
  let yChart=mix(tipChart,y,attachment);
  let u=(p.x/1.82+0.5)*(458.0-50.0)/512.0+50.0/512.0;
  let v=(170.0-yChart/0.005754411764705883)/341.0;

  let scan=atlas(vec2f(clamp(u,0.001,0.999)*0.75,clamp(v,0.001,0.999)*0.5));
  let border=min(min(u,1.0-u),min(v,1.0-v));
  let proximity=1.0-smoothstep(0.055,0.42,max(0.0,aperture(p.xy,cl,g)));
  // Outside the mobile lid, world-space distances determine the chart. The
  // apparent size of a pore follows the surface under a moving camera.
  let orbital=mix(p.xy*(1.025/1.065),vec2f(p.x,yChart),proximity);
  let cheekUv=outerPlateUV(orbital);
  // Continue the SAME nasal/temporal material outside the capture. Along its
  // border the chart and its low-frequency color have identical values.
  let outside=cheekUv-clamp(cheekUv,vec2f(0),vec2f(1));
  let extendedUv=cheekUv+vec2f(outside.y,-outside.x)*0.31;
  let chart=1.0-abs(2.0*fract(extendedUv*0.5)-1.0);
  let face=plate(vec2f(2048,1024),vec2f(2048,1024),chart);
  let faceLow=plate(vec2f(1536,272),vec2f(384,192),chart);
  let lidLow=plate(vec2f(1536,0),vec2f(384,256),vec2f(u,v));
  let coarse=smoothstep(-0.09,0.245,border);
  let fine=smoothstep(0.015,0.128,border);
  let low=mix(faceLow,lidLow,coarse);
  let faceDetail=clamp(face/max(faceLow,vec3f(0.008)),vec3f(0.25),vec3f(3.0));
  let scanDetail=clamp(scan/max(lidLow,vec3f(0.008)),vec3f(0.25),vec3f(3.0));
  let restColor=low*mix(faceDetail,scanDetail,fine);
  // During closure the superior tarsal skin unfolds down over the cornea.
  // Register the closed-lid plate to its curved lash line, just above the lashes.
  let section=clamp(p.x/0.91,-1.0,1.0);
  let closedSeam=0.462+0.073*(1.0-section*section);
  let above=p.y-lids.x;
  // Match the moving waterline while keeping the upper orbital skin fixed at
  // the brow. The frontal open scan contains a baked socket crease there.
  let brow=0.93;
  let browV=outerPlateUV(vec2f(p.x,brow)).y;
  let closedV=mix(closedSeam-0.026,browV,above/(brow-lids.x));
  let closedUv=vec2f(0.462+0.252*p.x,closedV);
  let closedChart=1.0-abs(2.0*fract(closedUv*0.5)-1.0);
  let unfolded=plate(vec2f(2048,1024),vec2f(2048,1024),closedChart);
  let upperSkin=smoothstep(0.008,0.086,above)
    *(1.0-smoothstep(0.86,1.17,abs(p.x)))*(1.0-smoothstep(0.90,1.19,p.y));
  // Reconstruct the narrow photographed shadow between the nasal lid and
  // brow from the broad albedos on either shoulder of the fold. Preserve the
  // high-frequency pore detail and let the moving surface cast its own shadow.
  let foldU=clamp(u-0.335,-0.31,0.12);
  let foldV=0.118+3.8*foldU*foldU+0.015*foldU;
  let slope=7.6*foldU+0.015;
  let across=normalize(vec2f(-slope,1.0));
  let foldDistance=(v-foldV)*across.y;
  let foldMask=smoothstep(0.035,0.096,u)*(1.0-smoothstep(0.36,0.48,u))
      *exp(-sq(foldDistance/0.037))*upperSkin;
  var foldColor=restColor;
  if(foldMask>0.001){
    let chartUV=vec2f(u,v);
    let high=plate(vec2f(1536,0),vec2f(384,256),chartUV-0.044*across);
    let lowSide=plate(vec2f(1536,0),vec2f(384,256),chartUV+0.037*across);
    let shoulders=mix(high,lowSide,0.59);
    let ratio=clamp(shoulders/max(lidLow,vec3f(0.012)),vec3f(1.0),vec3f(2.55));
    foldColor*=mix(vec3f(1.0),ratio,0.75*foldMask);
  }
  let movingSkin=smoothstep(0.12,0.80,cl)*upperSkin;
  let native=mix(foldColor,unfolded,movingSkin);
  if(params.skinBed<0.5 || params.skinLayer<=0.0){return nativeSkinTint(native);}
  // The lash line and brow anchor this chart during a blink. The free lid
  // unfurls over the globe and the scales grow smaller towards its wet rim.
  let restY=mix(yChart,p.y,smoothstep(0.78,1.24,abs(p.x)));
  let flow=vec2f(p.x+0.055*sin(2.4*restY),-restY-0.16*p.x*p.x+0.055*p.x);
  let chartPt=vec2f(0.49,0.52)+flow*params.skinFrequency*0.45;
  // Wet mucosa ends at the canthi. Outside them a distance to the
  // infinite margin ordinate would paint a stripe across the face.
  let cornerDistance=max(abs(p.x)-0.892,0.0);
  let rim=1.0-smoothstep(0.012,0.068,length(vec2f(offset,cornerDistance*1.65)));
  var material=skinSample(chartPt);
  if(params.skinBed>1.5 && params.skinBed<2.5){
    let ring=(1.0-smoothstep(0.10,0.32,offset))*(1.0-smoothstep(0.69,0.93,abs(p.x)));
    let down=select(-1.0,1.0,upper);
    let fine=skinSample(vec2f(0.68+p.x*0.88,0.33+down*skinDistance*1.24)*params.skinFrequency);
    material=mix(material,fine,0.88*ring);
  }
  return tissuePalette(native,material,rim);

}
fn shadeSkin(p:vec3f,rd:vec3f,cl:f32,g:vec2f)->vec3f {
  let xy=orbitalXY(p);
  let edge=aperture(xy,cl,g);
  let margin=exp(-pow(max(edge,0.0)/0.14,2.0));
  let raw=lidMap(p,cl,g);
  let blood=clamp((raw.r-raw.g*1.7)/max(raw.r,0.04),0.0,1.0);
  let moist=clamp(blood*0.60+margin*0.52,0.0,1.0)*params.wetness;
  let pigment=clamp(params.skinRedness*0.75,0.0,1.0);
  let melanin=dot(raw,vec3f(0.30,0.55,0.15));
  let chroma=mix(mix(0.54,0.85,pigment),1.0,select(0.0,params.skinLayer,params.skinBed>0.5));
  let base=mix(vec3f(melanin),raw,chroma)*mix(vec3f(0.875,1.01,1.045),vec3f(0.91,0.99,1.015),smoothstep(0.0,1.0,params.skinBed));
  let n=tissueNormal(p,cl,g);
  let tangent=normalize(cross(select(vec3f(0,1,0),vec3f(1,0,0),abs(n.y)>0.9),n));
  let bitangent=cross(n,tangent);
  let weights=vec3f(0.32,0.52,0.16);
  let relief=dot(raw,weights);
  let dx=dot(lidMap(p+0.003*tangent,cl,g),weights)-relief;
  let dy=dot(lidMap(p+0.003*bitangent,cl,g),weights)-relief;
  let normal=normalize(n-params.poreStrength*3.2*(dx*tangent+dy*bitangent));
  let rough=mix(clamp(params.skinRoughness+0.13,0.25,0.92),0.34,moist*0.68);
  // Hemispherical clearance at two scales selectively occludes indirect light.
  let aoNear=clamp(tissue(p+n*0.038,cl,g)/0.038,0.0,1.0);
  let aoFar=clamp(tissue(p+n*0.16,cl,g)/0.16,0.0,1.0);
  let ao=mix(1.0,0.35+0.65*(0.65*aoNear+0.35*aoFar),clamp(params.contactOcclusion,0.0,1.0));
  let key=keyDir();
  let direct=max(dot(normal,key),0.0);
  // Approximate a diffusion profile in surface space. The red channel gathers
  // farther across the terminator and the fold than the green and blue.
  let along=normalize(key-n*dot(n,key)+0.0001*tangent);
  let wide=tissueNormal(p+along*0.055,cl,g);
  let narrow=tissueNormal(p+along*0.018,cl,g);
  let low=vec3f(max(dot(wide,key),0.0),max(dot(narrow,key),0.0),max(dot(n,key),0.0));
  let scattering=clamp(params.translucency*(0.48+0.40*blood),0.0,0.94);
  let light=mix(vec3f(direct),low,scattering);
  let visibility=lidLight(p+n*0.012,cl,g);
  let softShadow=mix(vec3f(visibility),vec3f(0.24,0.085,0.035)+vec3f(0.76,0.915,0.965)*visibility,scattering);
  let diffuse=base*(vec3f(0.16,0.17,0.20)*ao+light*softShadow*keyColor()*params.lightIntensity*1.38);
  let spec=specular(normal,-rd,key,rough,0.026)*keyColor()*params.lightIntensity*visibility*0.35;
  let lower=lidEdges(xy.x,cl,g).y;
  let meniscus=exp(-sq((xy.y-lower-0.008)/0.024))*(1.0-smoothstep(0.74,0.91,abs(xy.x)));
  let film=roomRadiance(reflect(rd,normal))*(0.002*moist*moist+0.0028*meniscus*mix(0.35,1.0,blood))*params.wetness;
  let rim=exp(-sq((edge-0.058)/0.071))*params.wetness*params.skinSpecular;
  let towardSource=max(dot(reflect(rd,normal),key),0.0);
  let moistLobe=pow(towardSource,21.0)*moist*rim*keyColor()*params.lightIntensity*0.085;
  return diffuse*0.82+(spec+film)*params.skinSpecular*0.86+moistLobe;

}

// Follicle positions and growth directions are fixed in head space. Curl is
// measured in the tangent frame of the moving lid, including during closure.
struct LashCurve { a:vec3f,b:vec3f,c:vec3f };
fn rayBox(origin:vec3f,inverse:vec3f,lo:vec3f,hi:vec3f,limit:f32)->bool {
  let first=(lo-origin)*inverse;let last=(hi-origin)*inverse;
  let near=min(first,last);let far=max(first,last);
  return max(0.0,max(near.x,max(near.y,near.z)))<=min(limit,min(far.x,min(far.y,far.z)));
}
fn lashPigment()->vec3f {
 let hue=params.lashHue/360.0;
 let wheel=clamp(abs(fract(hue+vec3f(0.0,0.6666667,0.3333333))*6.0-3.0)-1.0,vec3f(0),vec3f(1));
 let rgb=params.lashValue*mix(vec3f(1),wheel,params.lashSaturation);
 return select(rgb/12.92,pow((rgb+0.055)/1.055,vec3f(2.4)),rgb>vec3f(0.04045));
}
fn lashBounds(ro:vec3f,inv:vec3f,limit:f32,x:i32,row:i32)->bool {
 let lo=textureLoad(inputTexture3,vec2i(x,row),0);
 if(lo.w<=0.0){return false;}
 return rayBox(ro,inv,lo.xyz,textureLoad(inputTexture3,vec2i(x+1,row),0).xyz,limit);
}
fn lashesOver(base:vec3f,ro:vec3f,rd:vec3f,limit:f32,row:i32,cone:f32)->vec3f {
 if(params.lashes<=0.0){return base;}
 let inverse=select(vec3f(-1),vec3f(1),rd>=vec3f(0))/max(abs(rd),vec3f(0.000001));
 let coating=smoothstep(1.0,3.0,params.lashes);
 var opacity=0.0;var melanin=0.0;var sheen=0.0;var fibreLight=1.0;var contact=0.0;
 let receiver=ro+rd*limit;
 let candidates=8*i32(ceil(clamp(params.lashes,0.0,3.0)));
 for(var block=0;block<6;block++){
  if(!lashBounds(ro,inverse,limit,1776+block*2,row)){continue;}
  for(var k=0;k<4;k++){
   let group=4*block+k;
   if(!lashBounds(ro,inverse,limit,1728+group*2,row)){continue;}
   for(var j=0;j<candidates;j++){
    let col=72*group+3*j;
    let a4=textureLoad(inputTexture3,vec2i(col,row),0);
    let presence=a4.w;
    if(presence<=0.0){continue;}
    let b4=textureLoad(inputTexture3,vec2i(col+1,row),0);
    let c4=textureLoad(inputTexture3,vec2i(col+2,row),0);
    let curve=LashCurve(a4.xyz,b4.xyz,c4.xyz);
      let aa=max(cone*dot(curve.a-ro,rd)*0.63,0.00023);
      // An occluding root casts a short penumbra onto its receiving lid.
      let light=keyDir();let separation=curve.a-receiver;let alongLight=dot(separation,light);
      let shaft=b4.w;
      let penumbra=shaft*2.0+0.23*max(0.0,alongLight);
      let footprint=length(separation-light*alongLight);
      let nearRoot=1.0-smoothstep(0.006,0.059,length(separation));
      contact=max(contact,presence*nearRoot*(1.0-smoothstep(0.0,penumbra+0.006,footprint)));
      let pad=vec3f(shaft+aa);
      if(!rayBox(ro,inverse,min(curve.a,min(curve.b,curve.c))-pad,max(curve.a,max(curve.b,curve.c))+pad,limit)){continue;}
    // Seed the closest point on the projected Bezier with four short chords.
    // Newton refinement evaluates the curved shaft itself at any magnification.
    let A=curve.a-ro;let B=2.0*(curve.b-curve.a);let C=curve.a-2.0*curve.b+curve.c;
    let P=A-rd*dot(A,rd);let Q=B-rd*dot(B,rd);let R=C-rd*dot(C,rd);
    var best=0.0;var bestD=dot(P,P);var prev=P;
    for(var segment=1;segment<=4;segment++){
     let end=f32(segment)*0.25;let next=P+end*(Q+end*R);
     let chord=next-prev;let u=clamp(-dot(prev,chord)/max(dot(chord,chord),1e-10),0.0,1.0);
     let v=prev+u*chord;let dd=dot(v,v);
     if(dd<bestD){best=end+(u-1.0)*0.25;bestD=dd;}
     prev=next;
    }
    var h=best;
    for(var walk=0;walk<2;walk++){
     let v=P+h*(Q+h*R);let deriv=Q+2.0*h*R;
     let denom=dot(deriv,deriv)+2.0*dot(v,R);
     if(denom>1e-8){h=clamp(h-dot(v,deriv)/denom,0.0,1.0);}
    }
    let t=dot(A+h*(B+h*C),rd);
    if(t<=0.0 || t>=limit){continue;}
    let radius=shaft*(1.0-0.90*pow(h,1.48));
    let distance=length(P+h*(Q+h*R));
    let cover=(1.0-smoothstep(max(0.0,radius-aa),radius+aa,distance))*min(1.0,radius/aa)*presence;
    if(cover>opacity){
     opacity=cover;melanin=c4.w;let tangent=normalize(B+2.0*h*C);
     let diffuse=sqrt(max(0.0,1.0-sq(dot(tangent,keyDir()))));
     let rootShadow=mix(0.35,1.0,smoothstep(0.0,0.33,h));
     fibreLight=rootShadow*(0.50+0.50*diffuse);
     sheen=rootShadow*pow(max(0.0,1.0-sq(dot(tangent,normalize(keyDir()-rd)))),12.0);
    }
   }
  }
 }
  let pigment=lashPigment()*mix(0.14,1.86,melanin);
  let hair=fibreLight*pigment*(vec3f(0.26)+0.74*keyColor()*params.lightIntensity)
    +sheen*keyColor()*params.lightIntensity*mix(0.015,0.031,coating);
  return mix(base*(1.0-0.24*contact),hair,opacity);
}

struct Socket { center:vec3f, scale:f32, basis:mat3x3f, identity:f32 };
const clusterPositions=array<vec4f,8>(
  vec4f(0.77,-0.14,0.98,1.02),vec4f(-1.00,0.29,0.80,0.70),
  vec4f(-0.21,1.16,0.61,0.56),vec4f(-1.54,-0.88,0.41,0.57),
  vec4f(2.05,0.40,0.49,0.61),vec4f(0.31,-1.21,0.39,0.52),
  vec4f(-2.30,1.04,0.32,0.46),vec4f(1.76,-0.93,0.28,0.42));
const orientations=array<vec3f,8>(
 vec3f(0.23,-0.04,-0.25),vec3f(-0.46,0.21,0.36),vec3f(-0.06,0.96,-0.72),vec3f(-0.74,-0.45,-0.42),
 vec3f(0.92,0.26,0.48),vec3f(0.08,-0.85,0.90),vec3f(-0.91,0.48,-0.23),vec3f(1.03,-0.70,0.55));
// A contraction travels down the mantle. Globes ride their sockets as rigid
// bodies. Sampling the inverse displacement keeps pores attached to the skin.
fn mantleDisplacement(p:vec3f)->vec3f {
 let phase=frameU.time*2.16-1.36*p.x+0.53*p.y-0.41*p.z;
 let beat=sin(phase)+0.23*sin(2.0*phase-0.75);
 let breath=sin(frameU.time*1.04-0.48*p.x+0.62*p.z);
 let outward=(p-vec3f(-0.12,-0.10,-0.28))/vec3f(2.38,1.54,1.67);
 return 0.068*breath*vec3f(0.50,1.0,0.86)*outward
      +0.051*beat*vec3f(0.46*outward.x,0.76*outward.y+0.32,0.8*outward.z);
}
fn socketAt(i:i32,paired:bool)->Socket {
 var pos=clusterPositions[i];var pose=orientations[i];var handedness=select(1.0,-1.0,i%3==1);
 if(paired){
   let side=select(-1.0,1.0,i==1);
   pos=vec4f(1.64*side,0.012*side,-0.08,1.0-0.011*side);
   pose=vec3f(0.038*side,0.012,-0.021*side); handedness=side;
 }
 let forward=vec3f(sin(pose.x)*cos(pose.y),sin(pose.y),cos(pose.x)*cos(pose.y));
 var placement=vec3f(pos.xy*params.spacing,pos.z);
 if(!paired){
   let radii=vec3f(2.06,1.26,1.34);
   let surfaceNormal=normalize(vec3f(forward.xy*params.spacing,forward.z));
   let support=radii*radii*surfaceNormal/length(radii*surfaceNormal);
   let onMantle=vec3f(-0.08,0.0,-0.28)+support+0.12*pos.w*surfaceNormal;
   placement=mix(vec3f(pos.xy*params.spacing,pos.z),onMantle,0.36);
   placement+=surfaceNormal*0.25*pos.w;
   placement+=mantleDisplacement(placement);
 }
 let side=normalize(cross(vec3f(0,1,0),forward));let up=cross(forward,side);
 let a=cos(pose.z);let b=sin(pose.z);
 return Socket(placement,pos.w,
   mat3x3f((side*a+up*b)*handedness,up*a-side*b,forward),f32(i));
}
// Outside the orbital charts a continuous dermal surface carries the furrows
// between the sockets. Both material coordinates are anchored in the tissue.
fn skinPatch(uv:vec2f,origin:vec2f,extent:vec2f)->vec3f {
