fn shapedMargins(x: f32) -> vec2f {
  let index = clamp((x + 0.91) / 1.82, 0.0, 1.0) * 48.0;
  let i = i32(floor(index));
  let t = fract(index);
  let a = marginKnots[max(i-1,0)]; let b = marginKnots[i];
  let c = marginKnots[min(i+1,48)]; let d = marginKnots[min(i+2,48)];
  return b + 0.5*t*(c-a+t*(2.0*a-5.0*b+4.0*c-d+t*(3.0*(b-c)+d-a)));
}
fn edgesFor(x:f32,closure:f32,follow:f32,opening:f32) -> vec2f {
  let rest = shapedMargins(x);
  let canthalWeight=1.0-smoothstep(0.46,0.91,abs(x));
  let arc=rest.x-rest.y;
  let seam=mix(rest.y,rest.x,0.17+0.045*x);
  let resting=vec2f(seam)+(rest-seam)*opening;
  let action=arc*vec2f(params.browLift*(0.068+0.16*x),params.lidTension*(0.12+0.045*x));
  let lateral=smoothstep(0.54,0.89,x);
  let medial=exp(-sq((x+0.80)/0.105));
  let open=resting+action+canthalWeight*follow*vec2f(0.56,0.19)
    +arc*vec2f(-0.075*lateral+0.024*medial,0.075*lateral+0.033*medial);
  // The lateral margin lags the centre. The lower lid gathers gently and
  // meets the descending upper lid on the same curved seam at full closure.
  let wave=closure*(1.0-closure);
  let upper=clamp(closure+wave*(0.18-0.35*x-0.21*x*x),0.0,1.0);
  let lower=clamp(closure-wave*(0.54+0.16*x),0.0,1.0);
  let meeting=seam+canthalWeight*follow*0.13-0.035*arc*(1.0-x*x);
  return vec2f(mix(open.x,meeting,upper),mix(open.y,meeting,lower));
}
fn lidEdges(x:f32,closure:f32,g:vec2f)->vec2f {return edgesFor(x,closure,lidFollowPitch,expressiveOpening);}
fn aperture(p: vec2f,closure: f32,g: vec2f) -> f32 {
  let lids=lidEdges(p.x,closure,g);
  let distance=max(p.y-lids.x,lids.y-p.y);
  let end=abs(p.x)-0.91;
  return length(max(vec2f(end,distance),vec2f(0)))+min(max(end,distance),0.0);
}
