fn pullFor(xy:vec2f,temporalDelta:vec2f,nasalDelta:vec2f)->vec2f {
  let temporal=(xy-vec2f(0.89,0.0))*vec2f(0.95,1.39);
  let nasal=(xy-vec2f(-0.90,-0.08))*vec2f(1.11,1.52);
  let falloff=exp(-2.45*vec2f(dot(temporal,temporal),dot(nasal,nasal)));
  return temporalDelta*falloff.x+nasalDelta*falloff.y;
}
