 let medial=xy.x+0.08;
 let u=vec2f(medial*0.68,(xy.y-0.55+0.10*xy.x)*1.44);
 let l=vec2f((xy.x-0.12)*0.72,(xy.y+0.54-0.06*xy.x)*1.48);
 let w=max(vec2f(0),1.0-vec2f(dot(u,u),dot(l,l)));
