  let t=clamp(0.5+0.5*(b-a)/r,0.0,1.0);
  return mix(b,a,t)-r*t*(1.0-t);
}
fn tissue(p:vec3f,cl:f32,g:vec2f)->f32 {
  let xy=orbitalXY(p);
  let e=aperture(xy,cl,g);
  let lids=lidEdges(xy.x,cl,g);
  let upper=smoothstep(-0.075,0.063,xy.y-mix(lids.y,lids.x,0.24));
  let globe=length(p)-1.0;
  let cap=length(rotateToEye(p,g)-vec3f(0,0,capCenter))-capRadius;
  let optical=mergeDistance(globe,cap,0.027+0.080*upper*smoothstep(-0.02,0.16,e));
  // Start below the wet surface, roll up toward the tarsal plate, then settle
  // into the fold. No vertical extrusion at the free edge or either canthus.
  let canthus=smoothstep(0.68,0.97,abs(xy.x));
  let width=mix(mix(0.109,0.129,upper),0.075,canthus);
  let rise=smoothstep(-0.033,width,e);
  let body=mix(0.059,0.076,upper);
  let crest=0.010*exp(-sq((e-0.087)/0.073));
  let unfold=cl*upper*(1.0-canthus);
  let fold=0.017*(1.0-0.50*upper*exp(-sq((xy.x+0.56)/0.31)))*(1.0-0.64*unfold)*exp(-sq((e-0.245-0.10*unfold-0.028*sin(xy.x*4.0))/0.092));
  let innerOffset=mix(-0.028,0.026,smoothstep(0.91,1.0,cl));
  var relief=0.0;
  if(params.sceneMode<0.5){relief=dot(mobileBands(xy),vec2f(upperDrag.z,lowerDrag.z));}
  let shell=optical-mix(innerOffset,body+crest-fold+relief,rise);
  let nasalBridge=xy*1.025-vec2f(-1.16,-0.27);
  let bridge=exp(-dot(nasalBridge*nasalBridge,vec2f(2.3,2.5)));
  let brow=exp(-sq((1.025*(xy.y+0.09*xy.x)-0.73)/0.52));
  // A medial fat pad supports the roof of the orbit above the inner corner.
  // Its broad union keeps a grazing key from catching a hard shelf.
  let cushion=exp(-sq((xy.x+0.86)/0.40)-sq((xy.y-0.56)/0.38));
  // Let the wet inner corner recede into the nasal tissue along an oblique crease.
  let nasalRecess=0.164*exp(-sq((xy.x+0.925)/0.152)-sq((xy.y+0.082-0.21*(xy.x+0.91))/0.107));
  let temporalRecess=0.046*exp(-sq((xy.x-0.914)/0.128)-sq((xy.y-0.09*(xy.x-0.91))/0.097));
  let groove=nasalRecess+temporalRecess;
  let cheek=0.22-groove+0.085*cushion+0.32*smoothstep(0.72,1.23,length(xy))+0.14*bridge+0.13*brow+relief;
  return mergeDistance(shell,(p.z-cheek)*0.87,0.006+0.070*cushion+0.23*smoothstep(0.02,0.22,e));
}
